insert into public.recipes
  (slug, category, is_pp, image, minutes, calories, servings, difficulty, title, description, ingredients, steps, tags)
values
  ('salat-cezar-s-kuricey', 'salad', false, null, 25, 320, 3, 'easy',
   '{"ru":"Салат «Цезарь» с курицей","en":"Chicken Caesar salad","ua":"Салат «Цезар» з куркою"}'::jsonb,
   '{"ru":"Хрустящий салат ромэн с обжаренной курицей, сухариками и пармезаном под кремовым соусом. Классика, которую любят все, — сытно и по-ресторанному вкусно.","en":"Crisp romaine with seared chicken, croutons and parmesan in a creamy dressing. A crowd-pleasing classic — filling and restaurant-good.","ua":"Хрусткий салат ромен з обсмаженою куркою, сухариками й пармезаном під кремовим соусом. Класика, яку люблять усі, — ситно й по-ресторанному смачно."}'::jsonb,
   '{"ru":["Куриное филе — 300 г","Салат ромэн — 1 большой пучок","Пармезан — 50 г","Белый хлеб — 3 ломтика","Чеснок — 1 зубчик","Майонез — 3 ст. л.","Горчица — 1 ч. л.","Лимонный сок — 1 ст. л.","Оливковое масло — 2 ст. л."],"en":["Chicken breast — 300 g","Romaine lettuce — 1 large head","Parmesan — 50 g","White bread — 3 slices","Garlic — 1 clove","Mayonnaise — 3 tbsp","Mustard — 1 tsp","Lemon juice — 1 tbsp","Olive oil — 2 tbsp"],"ua":["Куряче філе — 300 г","Салат ромен — 1 великий пучок","Пармезан — 50 г","Білий хліб — 3 скибочки","Часник — 1 зубчик","Майонез — 3 ст. л.","Гірчиця — 1 ч. л.","Лимонний сік — 1 ст. л.","Оливкова олія — 2 ст. л."]}'::jsonb,
   '{"ru":["Обжарьте курицу до румяности и нарежьте полосками.","Подсушите кубики хлеба на сковороде с чесноком до хруста.","Смешайте майонез, горчицу, лимонный сок и часть пармезана в соус.","Порвите салат руками, заправьте соусом.","Выложите курицу, сухарики и стружку пармезана сверху."],"en":["Sear the chicken until golden and slice into strips.","Toast bread cubes in a pan with garlic until crisp.","Mix mayo, mustard, lemon juice and some parmesan into a dressing.","Tear the lettuce by hand and toss with the dressing.","Top with the chicken, croutons and shaved parmesan."],"ua":["Обсмажте курку до рум''яності й наріжте смужками.","Підсушіть кубики хліба на сковороді з часником до хрускоту.","Змішайте майонез, гірчицю, лимонний сік і частину пармезану в соус.","Порвіть салат руками, заправте соусом.","Викладіть курку, сухарики й стружку пармезану зверху."]}'::jsonb,
   '{"ru":["салат","курица","цезарь"],"en":["salad","chicken","caesar"],"ua":["салат","курка","цезар"]}'::jsonb)
on conflict (slug) do update set
  category = excluded.category,
  is_pp = excluded.is_pp,
  minutes = excluded.minutes,
  calories = excluded.calories,
  servings = excluded.servings,
  difficulty = excluded.difficulty,
  title = excluded.title,
  description = excluded.description,
  ingredients = excluded.ingredients,
  steps = excluded.steps,
  tags = excluded.tags;

insert into public.recipes
  (slug, category, is_pp, image, minutes, calories, servings, difficulty, title, description, ingredients, steps, tags)
values
  ('salat-olivye', 'salad', false, null, 40, 300, 6, 'easy',
   '{"ru":"Салат «Оливье»","en":"Olivier (Russian) salad","ua":"Салат «Олів''є»"}'::jsonb,
   '{"ru":"Тот самый праздничный оливье с колбасой, солёными огурцами и горошком под майонезом. Знакомый вкус, который собирает всю семью за столом.","en":"The classic festive Olivier with sausage, pickles and peas in mayonnaise. A familiar taste that gathers the whole family at the table.","ua":"Той самий святковий олів''є з ковбасою, солоними огірками й горошком під майонезом. Знайомий смак, що збирає всю родину за столом."}'::jsonb,
   '{"ru":["Картофель — 4 шт.","Морковь — 2 шт.","Яйца — 4 шт.","Варёная колбаса — 300 г","Солёные огурцы — 3 шт.","Зелёный горошек — 200 г","Лук — 1 шт.","Майонез — 150 г","Соль — по вкусу"],"en":["Potatoes — 4","Carrots — 2","Eggs — 4","Boiled sausage — 300 g","Pickles — 3","Green peas — 200 g","Onion — 1","Mayonnaise — 150 g","Salt — to taste"],"ua":["Картопля — 4 шт.","Морква — 2 шт.","Яйця — 4 шт.","Варена ковбаса — 300 г","Солоні огірки — 3 шт.","Зелений горошок — 200 г","Цибуля — 1 шт.","Майонез — 150 г","Сіль — до смаку"]}'::jsonb,
   '{"ru":["Отварите картофель, морковь и яйца, остудите и очистите.","Нарежьте всё мелкими кубиками одного размера.","Добавьте колбасу, огурцы, лук и горошек.","Заправьте майонезом, посолите и перемешайте.","Дайте салату настояться в холодильнике 1 час перед подачей."],"en":["Boil the potatoes, carrots and eggs, then cool and peel.","Dice everything into small, even cubes.","Add the sausage, pickles, onion and peas.","Dress with mayonnaise, season and mix.","Chill for 1 hour before serving so the flavours meld."],"ua":["Відваріть картоплю, моркву та яйця, остудіть і почистіть.","Наріжте все дрібними кубиками одного розміру.","Додайте ковбасу, огірки, цибулю й горошок.","Заправте майонезом, посоліть і перемішайте.","Дайте салату настоятися в холодильнику 1 годину перед подачею."]}'::jsonb,
   '{"ru":["салат","оливье","праздничное"],"en":["salad","olivier","festive"],"ua":["салат","олів''є","святкове"]}'::jsonb)
on conflict (slug) do update set
