insert into public.recipes
  (slug, category, is_pp, image, minutes, calories, servings, difficulty, title, description, ingredients, steps, tags)
values
  ('salat-mimoza', 'salad', false, null, 45, 320, 6, 'easy',
   '{"ru":"Салат «Мимоза» с рыбными консервами","en":"Mimosa layered fish salad","ua":"Салат «Мімоза» з рибними консервами"}'::jsonb,
   '{"ru":"Нежный слоёный салат с рыбными консервами, яйцом и сыром, посыпанный жёлтым желтком — как цветы мимозы. Тает во рту и всегда исчезает первым.","en":"A tender layered salad of canned fish, egg and cheese, topped with grated yolk like mimosa blossoms. It melts in the mouth and always disappears first.","ua":"Ніжний листковий салат із рибними консервами, яйцем і сиром, посипаний жовтим жовтком — як квіти мімози. Тане в роті й завжди зникає першим."}'::jsonb,
   '{"ru":["Рыбные консервы — 240 г","Яйца — 5 шт.","Картофель — 3 шт.","Морковь — 2 шт.","Твёрдый сыр — 100 г","Лук — 1 шт.","Майонез — 150 г","Соль — по вкусу"],"en":["Canned fish — 240 g","Eggs — 5","Potatoes — 3","Carrots — 2","Hard cheese — 100 g","Onion — 1","Mayonnaise — 150 g","Salt — to taste"],"ua":["Рибні консерви — 240 г","Яйця — 5 шт.","Картопля — 3 шт.","Морква — 2 шт.","Твердий сир — 100 г","Цибуля — 1 шт.","Майонез — 150 г","Сіль — до смаку"]}'::jsonb,
   '{"ru":["Отварите картофель, морковь и яйца, натрите на тёрке отдельно.","Разомните рыбу вилкой, удалив кости.","Выкладывайте слои: картофель, рыба с луком, морковь, сыр, белки.","Каждый слой промазывайте тонким слоем майонеза.","Верхний слой — тёртый желток. Дайте настояться 2 часа в холодильнике."],"en":["Boil potatoes, carrots and eggs, then grate each separately.","Mash the fish with a fork, removing any bones.","Layer: potato, fish with onion, carrot, cheese, egg whites.","Spread a thin layer of mayonnaise between each layer.","Top with grated yolk. Chill for 2 hours before serving."],"ua":["Відваріть картоплю, моркву та яйця, натріть на тертці окремо.","Розімніть рибу виделкою, видаливши кістки.","Викладайте шари: картопля, риба з цибулею, морква, сир, білки.","Кожен шар промазуйте тонким шаром майонезу.","Верхній шар — тертий жовток. Дайте настоятися 2 години в холодильнику."]}'::jsonb,
   '{"ru":["салат","мимоза","рыба","праздничное"],"en":["salad","mimosa","fish","festive"],"ua":["салат","мімоза","риба","святкове"]}'::jsonb)
