insert into public.recipes
  (slug, category, is_pp, image, minutes, calories, servings, difficulty, title, description, ingredients, steps, tags)
values
  ('vinegret', 'salad', true, null, 40, 150, 6, 'easy',
   '{"ru":"Винегрет","en":"Vinegret beet salad","ua":"Вінегрет"}'::jsonb,
   '{"ru":"Яркий постный салат из варёной свёклы, картофеля, моркови и солёных огурцов с квашеной капустой. Полезно, бюджетно и с той самой кислинкой.","en":"A vivid, lean salad of boiled beetroot, potato, carrot and pickles with sauerkraut. Wholesome, budget-friendly and with just the right tang.","ua":"Яскравий пісний салат із вареного буряка, картоплі, моркви й солоних огірків із квашеною капустою. Корисно, бюджетно й із тією самою кислинкою."}'::jsonb,
   '{"ru":["Свёкла — 2 шт.","Картофель — 3 шт.","Морковь — 2 шт.","Солёные огурцы — 3 шт.","Квашеная капуста — 150 г","Лук — 1 шт.","Зелёный горошек — 100 г","Растительное масло — 3 ст. л.","Соль — по вкусу"],"en":["Beetroot — 2","Potatoes — 3","Carrots — 2","Pickles — 3","Sauerkraut — 150 g","Onion — 1","Green peas — 100 g","Vegetable oil — 3 tbsp","Salt — to taste"],"ua":["Буряк — 2 шт.","Картопля — 3 шт.","Морква — 2 шт.","Солоні огірки — 3 шт.","Квашена капуста — 150 г","Цибуля — 1 шт.","Зелений горошок — 100 г","Олія — 3 ст. л.","Сіль — до смаку"]}'::jsonb,
   '{"ru":["Отварите свёклу, картофель и морковь, остудите и очистите.","Нарежьте все овощи мелкими кубиками.","Свёклу отдельно сбрызните маслом, чтобы не окрасила остальное.","Соедините все овощи, капусту, огурцы, лук и горошек.","Заправьте маслом, посолите и перемешайте."],"en":["Boil the beetroot, potato and carrot, then cool and peel.","Dice all the vegetables into small cubes.","Toss the beetroot with oil separately so it doesn''t stain the rest.","Combine all the veg, sauerkraut, pickles, onion and peas.","Dress with oil, season and mix."],"ua":["Відваріть буряк, картоплю й моркву, остудіть і почистіть.","Наріжте всі овочі дрібними кубиками.","Буряк окремо збризніть олією, щоб не забарвив решту.","Поєднайте всі овочі, капусту, огірки, цибулю й горошок.","Заправте олією, посоліть і перемішайте."]}'::jsonb,
   '{"ru":["ПП","салат","постное","свёкла"],"en":["healthy","salad","lean","beetroot"],"ua":["ПХ","салат","пісне","буряк"]}'::jsonb)
on conflict (slug) do update set
