insert into public.recipes
  (slug, category, is_pp, image, minutes, calories, servings, difficulty, title, description, ingredients, steps, tags)
values
  ('teplyy-salat-s-kuricey', 'salad', true, null, 25, 240, 2, 'easy',
   '{"ru":"Тёплый салат с курицей и овощами","en":"Warm chicken and vegetable salad","ua":"Теплий салат з куркою та овочами"}'::jsonb,
   '{"ru":"Сочная обжаренная курица на подушке из свежих овощей с лёгкой заправкой. Тёплое мясо и хрустящий салат — сытный ПП-обед, который не оставит тяжести.","en":"Juicy seared chicken on a bed of fresh vegetables with a light dressing. Warm meat and crisp salad — a filling healthy lunch that won''t weigh you down.","ua":"Соковита обсмажена курка на подушці зі свіжих овочів із легкою заправкою. Тепле м''ясо й хрусткий салат — ситний ПХ-обід, що не залишить тяжкості."}'::jsonb,
   '{"ru":["Куриное филе — 300 г","Салатный микс — 100 г","Помидоры черри — 150 г","Огурец — 1 шт.","Болгарский перец — 1 шт.","Оливковое масло — 2 ст. л.","Соевый соус — 1 ст. л.","Лимонный сок — 1 ст. л.","Соль и перец — по вкусу"],"en":["Chicken breast — 300 g","Salad mix — 100 g","Cherry tomatoes — 150 g","Cucumber — 1","Bell pepper — 1","Olive oil — 2 tbsp","Soy sauce — 1 tbsp","Lemon juice — 1 tbsp","Salt and pepper — to taste"],"ua":["Куряче філе — 300 г","Салатний мікс — 100 г","Помідори чері — 150 г","Огірок — 1 шт.","Болгарський перець — 1 шт.","Оливкова олія — 2 ст. л.","Соєвий соус — 1 ст. л.","Лимонний сік — 1 ст. л.","Сіль і перець — до смаку"]}'::jsonb,
   '{"ru":["Нарежьте курицу полосками и обжарьте до румяности.","Нарежьте овощи и выложите на тарелку с салатным миксом.","Смешайте масло, соевый соус и лимонный сок в заправку.","Выложите тёплую курицу поверх овощей.","Полейте заправкой и сразу подавайте, пока курица тёплая."],"en":["Slice the chicken into strips and sear until golden.","Chop the vegetables and arrange on a plate with the salad mix.","Mix oil, soy sauce and lemon juice into a dressing.","Place the warm chicken over the vegetables.","Drizzle with dressing and serve while the chicken is warm."],"ua":["Наріжте курку смужками й обсмажте до рум''яності.","Наріжте овочі й викладіть на тарілку із салатним міксом.","Змішайте олію, соєвий соус і лимонний сік у заправку.","Викладіть теплу курку поверх овочів.","Полийте заправкою й одразу подавайте, поки курка тепла."]}'::jsonb,
   '{"ru":["ПП","салат","курица","тёплый"],"en":["healthy","salad","chicken","warm"],"ua":["ПХ","салат","курка","теплий"]}'::jsonb)
