insert into public.recipes
  (slug, category, is_pp, image, minutes, calories, servings, difficulty, title, description, ingredients, steps, tags)
values
  ('salat-s-tuncom-i-fasolyu', 'salad', true, null, 15, 260, 3, 'easy',
   '{"ru":"Салат с тунцом и фасолью","en":"Tuna and bean salad","ua":"Салат з тунцем і квасолею"}'::jsonb,
   '{"ru":"Быстрый белковый салат из тунца, красной фасоли и свежих овощей с лёгкой заправкой. Готовится за 15 минут без варки — сытно, но легко.","en":"A quick protein salad of tuna, red beans and fresh vegetables with a light dressing. Ready in 15 minutes with no cooking — filling yet light.","ua":"Швидкий білковий салат із тунця, червоної квасолі та свіжих овочів із легкою заправкою. Готується за 15 хвилин без варіння — ситно, але легко."}'::jsonb,
   '{"ru":["Тунец консервированный — 240 г","Красная фасоль — 200 г","Помидоры — 2 шт.","Огурец — 1 шт.","Красный лук — половина","Кукуруза — 100 г","Оливковое масло — 2 ст. л.","Лимонный сок — 1 ст. л.","Зелень — по вкусу"],"en":["Canned tuna — 240 g","Red beans — 200 g","Tomatoes — 2","Cucumber — 1","Red onion — half","Sweetcorn — 100 g","Olive oil — 2 tbsp","Lemon juice — 1 tbsp","Herbs — to taste"],"ua":["Тунець консервований — 240 г","Червона квасоля — 200 г","Помідори — 2 шт.","Огірок — 1 шт.","Червона цибуля — половина","Кукурудза — 100 г","Оливкова олія — 2 ст. л.","Лимонний сік — 1 ст. л.","Зелень — до смаку"]}'::jsonb,
   '{"ru":["Слейте жидкость с тунца, фасоли и кукурузы.","Нарежьте помидоры, огурец и лук.","Соедините все ингредиенты в миске.","Заправьте маслом и лимонным соком, посолите.","Аккуратно перемешайте, чтобы тунец не превратился в пасту."],"en":["Drain the tuna, beans and sweetcorn.","Chop the tomatoes, cucumber and onion.","Combine all the ingredients in a bowl.","Dress with oil and lemon juice, then season.","Toss gently so the tuna doesn''t turn to paste."],"ua":["Злийте рідину з тунця, квасолі й кукурудзи.","Наріжте помідори, огірок і цибулю.","Поєднайте всі інгредієнти в мисці.","Заправте олією й лимонним соком, посоліть.","Обережно перемішайте, щоб тунець не перетворився на пасту."]}'::jsonb,
   '{"ru":["ПП","салат","тунец","быстро"],"en":["healthy","salad","tuna","quick"],"ua":["ПХ","салат","тунець","швидко"]}'::jsonb)
