insert into public.recipes
  (slug, category, is_pp, image, minutes, calories, servings, difficulty, title, description, ingredients, steps, tags)
values
  ('salat-s-krevetkami-i-avokado', 'salad', true, null, 20, 280, 2, 'easy',
   '{"ru":"Салат с креветками и авокадо","en":"Shrimp and avocado salad","ua":"Салат із креветками та авокадо"}'::jsonb,
   '{"ru":"Освежающий салат с сочными креветками, кремовым авокадо и черри под цитрусовой заправкой. Лёгкий, но эффектный — подойдёт и на ужин, и на праздничный стол.","en":"A refreshing salad of juicy shrimp, creamy avocado and cherry tomatoes in a citrus dressing. Light yet impressive — great for dinner or a special table.","ua":"Освіжаючий салат із соковитими креветками, кремовим авокадо й чері під цитрусовою заправкою. Легкий, але ефектний — підійде і на вечерю, і на святковий стіл."}'::jsonb,
   '{"ru":["Креветки — 250 г","Авокадо — 1 шт.","Помидоры черри — 150 г","Салатный микс — 80 г","Красный лук — половина","Оливковое масло — 2 ст. л.","Сок лайма — 1 ст. л.","Соль и перец — по вкусу"],"en":["Shrimp — 250 g","Avocado — 1","Cherry tomatoes — 150 g","Salad mix — 80 g","Red onion — half","Olive oil — 2 tbsp","Lime juice — 1 tbsp","Salt and pepper — to taste"],"ua":["Креветки — 250 г","Авокадо — 1 шт.","Помідори чері — 150 г","Салатний мікс — 80 г","Червона цибуля — половина","Оливкова олія — 2 ст. л.","Сік лайма — 1 ст. л.","Сіль і перець — до смаку"]}'::jsonb,
   '{"ru":["Обжарьте креветки 1–2 минуты и остудите.","Нарежьте авокадо, черри и лук.","Выложите салатный микс, сверху овощи и креветки.","Смешайте масло с соком лайма в заправку.","Полейте заправкой, посолите и сразу подавайте."],"en":["Sear the shrimp for 1–2 minutes and cool.","Slice the avocado, cherry tomatoes and onion.","Lay out the salad mix, then the vegetables and shrimp.","Mix oil with lime juice into a dressing.","Drizzle over, season and serve at once."],"ua":["Обсмажте креветки 1–2 хвилини й остудіть.","Наріжте авокадо, чері й цибулю.","Викладіть салатний мікс, зверху овочі й креветки.","Змішайте олію із соком лайма в заправку.","Полийте заправкою, посоліть і одразу подавайте."]}'::jsonb,
   '{"ru":["ПП","салат","креветки","авокадо"],"en":["healthy","salad","shrimp","avocado"],"ua":["ПХ","салат","креветки","авокадо"]}'::jsonb)
on conflict (slug) do update set
  category = excluded.category,
  is_pp = excluded.is_pp,
  minutes = excluded.minutes,
  calories = excluded.calories,
